contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint unlockTime, uint amount) public payable {
        require(address(this).balance >= amount);

        // Read the caller's balance before the Put call.
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));

        // The call that changes c's state: must always complete, never revert.
        bool reverted;
        try c.Put{value: amount}(unlockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read the caller's balance after the Put call.
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));

        // General rule: Put completes (no revert), adds at least the sent amount
        // to the caller's balance, and never decreases the existing balance.
        // The unlockTime is clamped to be strictly greater than block.timestamp.
        assert(
            !reverted &&
            afterBal >= beforeBal + amount &&
            afterUnlock > block.timestamp
        );
    }

    receive() external payable {}
}

