    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint deposit, uint unlockTime, uint collectAmt) public payable {
        require(address(this).balance >= deposit);
        require(deposit >= c.MinSum() - c.MinSum() + collectAmt);

        c.Put{value: deposit}(unlockTime);

        (uint unlockTimeBefore, uint balanceBefore) = c.Acc(address(this));

        bool reverted;
        try c.Collect(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint unlockTimeAfter, uint balanceAfter) = c.Acc(address(this));

        bool shouldRevert = !(balanceBefore >= c.MinSum() && balanceBefore >= collectAmt && block.timestamp > unlockTimeBefore);
        assert(reverted == shouldRevert && (reverted || balanceAfter == balanceBefore - collectAmt));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint putAmount, uint unlockTimeA, uint unlockTimeB, uint collectAmount) public payable {
        require(putAmount > 0 && collectAmount <= putAmount);
        require(putAmount <= address(this).balance);
        require(collectAmount <= putAmount);

        uint beforeTestBal = address(this).balance;

        // First Put to set an initial balance and unlock time
        c.Put{value: putAmount}(unlockTimeA);

        (uint unlockA, uint balA) = c.Acc(msg.sender);

        // Second Put should not decrease balance and must not revert
        c.Put{value: putAmount}(unlockTimeB);

        (uint unlockB, uint balB) = c.Acc(msg.sender);

        // Collect the entire balance after unlock time has passed (if any)
        if (collectAmount > 0 && block.timestamp > unlockB) {
            c.Collect{value: 0}(collectAmount);
        }

        (uint unlockAfter, uint balAfter) = c.Acc(msg.sender);

        // General rule: Put does not revert, increases balance by the sent amount (mod overflow),
        // and unlockTime is at least the current timestamp (and at least the supplied value if it is in the future).
        // Additionally, the test contract's balance decreases by exactly the sum of putAmount for each Put
        // and increases by collectAmount if Collect succeeded (i.e., if balAfter < balB then test balance increased by collectAmount).
        uint expectedTestBal = beforeTestBal - 2 * putAmount;
        if (balAfter < balB) {
            expectedTestBal += collectAmount;
        }

        assert(
            balB == balA + putAmount &&
            unlockB >= unlockA &&
            (unlockB == unlockTimeB || unlockB == block.timestamp || unlockB > unlockTimeB) &&
            address(this).balance == expectedTestBal
        );
    }

    receive() external payable {}
}
